function cq2Auto() { const f = String(S.forme || ""), a = S.activite || ""; if (a === "association" || /asso/i.test(f)) return "asso"; if (a === "sci" || /SCI/i.test(f)) return "sci"; if (/^(EI|EIRL|Entreprise individuelle|micro|LMNP|BNC)/i.test(f) || a === "independant") return "ei"; return "soc"; }
function cq2St() { const Q = S.cq2 ||= {}; Q.off ||= {}; Q.titles ||= {}; Q.texts ||= {}; Q.order ||= CQ2_SECT.map(x => x[0]); CQ2_SECT.forEach(x => { if (!Q.order.includes(x[0])) Q.order.push(x[0]); }); Q.opt = Object.assign({ n1: "1", varp: "1", zero: "0", round: "1", div: "1", flow: "1", dash: "1", color: "", exp: "" }, Q.opt || {}); Q.cab ||= {}; return Q; }
