const cq2X = (k, ex) => { const Q = cq2St(); if (Q.texts[k] != null && Q.texts[k] !== "") return Q.texts[k]; const f = CQ2_TXT[k]; return typeof f === "function" ? f(ex, cq2Prof()) : f || ""; };
/* indicateurs clés */
function cq2KPI(ex) { const one = e => { if (!e) return null; const c = compteResultat(e.debut, e.fin), b = bilan(e), m = soldeMap(e.debut, e.fin); const g = k => b.get(k).val;
    const cp = PASSIF[0][1].reduce((a, [k]) => a + g(k), 0); const imm = ACTIF[1][1].reduce((a, [k]) => a + g(k), 0); const dlt = g("P_ecr") + g("P_edv"); const prov = g("P_prov");
    const disp = g("A_disp") + g("A_vmp"); const conc = -sumPrefSign(m, ["519"], -1); const tr = disp - conc; const acE = ["A_smp", "A_sec", "A_spf", "A_sm", "A_avv", "A_cli", "A_acre", "A_cca"].reduce((a, k) => a + g(k), 0); const dtE = ["P_avr", "P_fou", "P_fisc", "P_dimm", "P_adet", "P_pca"].reduce((a, k) => a + g(k), 0);
    const caf = c.RN + c.v("C_dam") + c.v("C_dpr") - c.v("P_rep"); return { ca: c.CA, ebe: c.sig.EBE, rn: c.RN, re: c.RE, cp, fr: cp + dlt + prov + g("P_fded") - imm, bfr: acE - dtE, tr, det: dlt - disp, caf, tb: b.totA, eff: Number(S.effectif) || 0, c, b }; };
  const K = one(ex); K.p = one(prevEx(ex)); return K; }
