function cq2Report(ex, pages, only) { const Q = cq2St(); const pr = cq2Prof(); const pv = Q.opt.n1 === "1" ? prevEx(ex) : null; const keys = only ? [only] : Q.order.filter(k => cq2On(k) && CQ2_F[k] && (cq2Def(k)[2] !== "n1" || prevEx(ex))); const R = new Report("Comptes annuels " + ex.fin.slice(0, 4)); const P = R.pdf, M = R.M; const seen = {}; const noFoot = new Set(); const main = Q.opt.color || PC.navy;
  const sav = { navy: PC.navy, blue: PC.blue }; if (Q.opt.color) { PC.navy = Q.opt.color; PC.blue = Q.opt.color; }
  R.header = function () { P.rect(0, 0, P.W, 3, this._col || main); P.text(P.W - M, 22, pdfClean(S.nom + " | Comptes annuels " + ex.fin.slice(0, 4)), { size: 7.5, color: PC.ink2, align: "right" }); this.y = 54; if (this.section) { P.text(M, this.y, pdfClean(this.section), { size: 17, bold: true, color: PC.ink }); this.y += 15; if (this.sub && !/ \(suite\)$/.test(this.section)) { P.text(M, this.y, pdfClean(this.sub), { size: 8.5, color: PC.ink2 }); this.y += 6; } this.y += 16; } };
  const ctx = { ex, pv, pr, R, P, M, Q, keys, pages, seen, noFoot, page: (t, sub, part) => { R._col = cq2Col(part); if (!only && Q.opt.flow === "1" && part === "annexe" && ctx._lp === "annexe" && R.started && R.y < P.H - 260) { R.y += 18; P.rect(M, R.y - 11, 3, 15, R._col); P.text(M + 10, R.y, pdfClean(t), { size: 12.5, bold: true, color: PC.ink }); R.y += 12; if (sub) { P.text(M + 10, R.y, pdfClean(sub), { size: 8, color: PC.ink2 }); R.y += 6; } R.y += 12; R.section = t; R.sub = sub; R.rec.push({ title: t, sub, form: "", items: [] }); } else R.newPage(t, sub || ""); ctx._lp = part; seen[t] ||= P.pages.length; if (ctx.cur) seen["§" + ctx.cur] ||= P.pages.length; } };
  let lastPart = null;
  try { for (const k of keys) { const d = cq2Def(k); if (!only && Q.opt.div === "1" && d[2] !== lastPart && d[2] !== "pres") { cq2Divider(ctx, d[2]); } lastPart = d[2]; ctx.cur = k; try { CQ2_F[k](ctx); } catch (e) { logErr("comptes annuels " + k, e); ctx.page(cq2T(k), "", d[2]); R.para("Section indisponible : " + (e.message || e)); } } }
  finally { PC.navy = sav.navy; PC.blue = sav.blue; }
  R._cq2 = { seen, noFoot }; return R; }
function cq2Divider(ctx, part) { const { R, P, noFoot, seen } = ctx; const p = CQ2_PARTS.find(x => x[0] === part); if (!p) return; if (R.started) P.addPage(); R.started = true; R.section = ""; const col = cq2Col(part);
  P.rect(0, 0, P.W * 0.62, P.H * 0.42, col); P.rect(0, P.H * 0.42, P.W * 0.62, 5, PC.gold); const words = pdfClean(p[1]).split(" "); let line = "", y = 150; const L = []; words.forEach(w => { if (textW(line + " " + w, 30, true) > P.W * 0.62 - 90 && line) { L.push(line); line = w; } else line = line ? line + " " + w : w; }); L.push(line); L.forEach((l, i) => P.text(48, y + i * 36, l, { size: 30, bold: true, color: "#FFFFFF" }));
  noFoot.add(P.pages.length); seen["#" + part] = P.pages.length; ctx._lp = null; }
function cq2Finish(R, ex) { const P = R.pdf, M = R.M, Q = cq2St(); const n = P.pages.length; const note = Q.opt.pied || (cq2Cab().mission === "audit" ? "Voir le rapport du commissaire aux comptes" : "Voir le rapport de l'expert-comptable sur les comptes annuels") + (ex.cloture ? "" : " · comptes provisoires");
  P.pages.forEach((pg, i) => { if (R._cq2.noFoot.has(i + 1)) return; P.cur = pg; P.text(M, P.H - 22, pdfClean(note), { size: 7, color: PC.ink3 }); P.text(P.W - M, P.H - 22, "- " + (i + 1) + " -", { size: 7.5, color: PC.ink3, align: "right" }); });
  return P.output(); }
function cq2Build(ex, only) { if (only) return cq2Finish(cq2Report(ex, null, only), ex); const a = cq2Report(ex, null); const b = cq2Report(ex, a._cq2.seen); return cq2Finish(b, ex); }
/* tableaux */
const CQ2_C4 = [{ wrap: 1 }, { w: 78, align: "right" }, { w: 78, align: "right" }, { w: 78, align: "right" }, { w: 78, align: "right" }];
const CQ2_C3 = [{ wrap: 1 }, { w: 90, align: "right" }, { w: 90, align: "right" }, { w: 90, align: "right" }];
